#include <iostream>
#include <vector>
#include <string>
using namespace std;

int countDistinctSubsequences(string s) {
    int n = s.length();
    vector<long long> dp(n, 0);
    dp[0] = 1;
    for (int i = 1; i < n; i++) {
        dp[i] = 2 * dp[i-1];
        if (s[i] == s[i-1]) {
            dp[i] -= dp[i-2];
        }
    }
    return (int)(dp[n-1] % 1000000007);
}

int main() {
    string s = "abc";
    cout << countDistinctSubsequences(s) << endl;
    return 0;
}
